CREATE OR REPLACE FUNCTION public.report_colour_luminance(c text) RETURNS double precision LANGUAGE plpgsql IMMUTABLE SET search_path = public AS $$ DECLARE r double precision; g double precision; b double precision; BEGIN r := get_byte(decode(substr(c,2),'hex'),0)/255.0; g := get_byte(decode(substr(c,2),'hex'),1)/255.0; b := get_byte(decode(substr(c,2),'hex'),2)/255.0; RETURN 0.2126*(CASE WHEN r<=0.04045 THEN r/12.92 ELSE power((r+0.055)/1.055,2.4) END)+0.7152*(CASE WHEN g<=0.04045 THEN g/12.92 ELSE power((g+0.055)/1.055,2.4) END)+0.0722*(CASE WHEN b<=0.04045 THEN b/12.92 ELSE power((b+0.055)/1.055,2.4) END); END $$;
REVOKE ALL ON FUNCTION public.report_colour_luminance(text) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.validate_report_appearance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v jsonb; k text; c text; pair text[]; a double precision; b double precision; roles text[] := ARRAY['schoolName','schoolInfo','reportTitle','pageBackground','infoLabel','infoValue','infoBackground','infoBorder','tableTitle','columnHeading','rowHeading','columnBackground','rowBackground','tableBackground','tableBorder','tableText','conductLabel','conductText','commentHeading','commentText','commentBackground','commentBorder','designation','dates']; BEGIN
IF TG_OP='DELETE' THEN IF OLD.key<>'report_appearance' THEN RETURN OLD; END IF; v:=OLD.value; ELSE IF NEW.key<>'report_appearance' AND (TG_OP='INSERT' OR OLD.key<>'report_appearance') THEN RETURN NEW; END IF; v:=NEW.value; END IF;
IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR public.is_super_admin()) OR (CASE WHEN TG_OP='DELETE' THEN OLD.school_id ELSE NEW.school_id END) IS DISTINCT FROM public.current_user_school_id() THEN RAISE EXCEPTION 'Only an administrator of the current school can change report appearance.'; END IF;
IF TG_OP='UPDATE' AND (NEW.school_id IS DISTINCT FROM OLD.school_id OR NEW.key IS DISTINCT FROM OLD.key) THEN RAISE EXCEPTION 'Report appearance cannot be moved to another school or setting.'; END IF;
IF TG_OP='DELETE' THEN RETURN OLD; END IF;
IF jsonb_typeof(v)<>'object' THEN RAISE EXCEPTION 'Report appearance must be a colour configuration.'; END IF;
FOR k,c IN SELECT key,value FROM jsonb_each_text(v) LOOP IF NOT(k=ANY(roles)) OR c !~ '^#[0-9a-fA-F]{6}$' THEN RAISE EXCEPTION 'Invalid appearance colour.'; END IF; END LOOP;
IF v='{}'::jsonb THEN RETURN NEW; END IF;
FOREACH k IN ARRAY ARRAY['pageBackground','infoBackground','tableBackground','commentBackground'] LOOP IF public.report_colour_luminance(coalesce(v->>k,'#ffffff'))<0.65 THEN RAISE EXCEPTION 'Report backgrounds must stay light to protect images.'; END IF; END LOOP;
FOREACH pair SLICE 1 IN ARRAY ARRAY[['schoolName','pageBackground'],['schoolInfo','pageBackground'],['reportTitle','pageBackground'],['tableTitle','pageBackground'],['dates','pageBackground'],['infoLabel','infoBackground'],['infoValue','infoBackground'],['columnHeading','columnBackground'],['rowHeading','rowBackground'],['tableText','tableBackground'],['conductLabel','commentBackground'],['conductText','commentBackground'],['commentHeading','commentBackground'],['commentText','commentBackground'],['designation','commentBackground']] LOOP
 a:=public.report_colour_luminance(coalesce(v->>pair[1],'#111111')); b:=public.report_colour_luminance(coalesce(v->>pair[2], CASE WHEN pair[2] IN ('columnBackground','rowBackground') THEN '#f1f3f7' ELSE '#ffffff' END)); IF (greatest(a,b)+0.05)/(least(a,b)+0.05)<4.5 THEN RAISE EXCEPTION 'Text needs a contrast ratio of at least 4.5:1.'; END IF;
END LOOP; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_report_appearance() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER validate_school_report_appearance BEFORE INSERT OR UPDATE OR DELETE ON public.system_settings FOR EACH ROW EXECUTE FUNCTION public.validate_report_appearance();